export const teams=[['Faculty','Faculty','faculty','faculty member'],['PhD scholars','PhD scholars','phd','PhD scholar'],['M.Tech students','Master’s students','masters','master’s student'],['Junior research fellows','Junior Research Fellows (JRFs)','jrf','JRF'],['Project students','Project students','projects','project student'],['Alumni','Alumni','alumni','alumnus']];
export const sections={profile:'Profile',about:'About',research:'Research areas',grant:'Research support',publications:'Publications',book:'Book',publicationLinks:'Publication links',education:'Education',fellowship:'Fellowship',contact:'Contact',group:'Group page',members:'Group members'};
export const fields={profile:['name','shortName','institution','department','role','intro','portrait','location','universityUrl','email','orcidUrl','scholarUrl'],about:['text'],research:['label','title','description'],grant:['label','title','funder','description'],publications:['year','title','url','authors','journal'],book:['label','title','authors','note','url'],publicationLinks:['listUrl'],education:['year','degree','institution','note'],fellowship:['title','description'],contact:['heading','address','googleSiteUrl'],group:['title','description','enquiries'],members:['name','category','role','research','photo','email','link']};
export const lists=['research','publications','education','members'];
export const isUrl=k=>/url$/i.test(k)||['link','photo','portrait'].includes(k);
export function safeUrl(value){if(!value)return '';if(/[\s\\<>"']/.test(value)||value.startsWith('//'))return '';if(/^https?:\/\//i.test(value)){try{return new URL(value).href;}catch{return '';}}return /^[a-zA-Z0-9_./%-]+$/.test(value)&&!value.includes('..')?value:'';}
export function validate(content){for(const [section,keys] of Object.entries(fields)){const raw=content[section];const items=lists.includes(section)?raw:[raw];if(!Array.isArray(items)||items.length>200)throw Error(section+': invalid entries');for(const item of items){if(!item||typeof item!=='object')throw Error(section+': invalid entry');for(const key of keys){const v=item[key];if(typeof v!=='string'||v.length>12000)throw Error(section+' / '+key+': invalid text');if(isUrl(key)&&v&&!safeUrl(v))throw Error(section+' / '+key+': use an https:// URL or local asset path');if(key==='email'&&v&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v))throw Error(section+': invalid email');}if(section==='members'&&(!item.name.trim()||!teams.some(t=>t[0]===item.category)))throw Error('Each member needs a name and category');}}if(!content.profile.name.trim()||!content.group.title.trim())throw Error('Profile and group names are required');return content;}
export function blank(section,category){return Object.fromEntries(fields[section].map(key=>[key,key==='category'?(category||'PhD scholars'):'']));}
